const ids = ["1:24","1:27","1:32","1:42","1:182","1:183","1:184","1:185","1:186","1:201","1:207","1:208","1:209","1:218","1:154","1:156","1:173","1:158","1:161","1:164","1:166","1:169","1:171","1:167","1:162","1:172","1:163","1:160","1:170","1:165","1:159","1:168"];
const out = [];
for (const id of ids) {
  const n = await figma.getNodeByIdAsync(id);
  if (!n) { out.push({id, missing:true}); continue; }
  const info = {id, name:n.name, type:n.type, w:Math.round(n.width), h:Math.round(n.height)};
  if (n.type === "COMPONENT" || n.type === "FRAME") {
    info.children = n.children.map(c => ({name:c.name, type:c.type, w:Math.round(c.width), h:Math.round(c.height), chars: c.type==="TEXT"? c.characters : undefined, fontName: c.type==="TEXT"? c.fontName : undefined, fontSize: c.type==="TEXT"? c.fontSize : undefined, fills: c.fills && c.fills.length ? c.fills.map(f=>f.type==="IMAGE"?"IMAGE":(f.type==="SOLID"?("#"+Object.values(f.color).map(v=>Math.round(v*255).toString(16).padStart(2,"0")).join("")):f.type)) : undefined}));
    info.fills = n.fills && n.fills.length ? n.fills.map(f=>f.type==="IMAGE"?"IMAGE":(f.type==="SOLID"?"SOLID":f.type)) : [];
    info.layoutMode = n.layoutMode;
  }
  out.push(info);
}
return JSON.stringify(out, null, 1);

