const page = await figma.getNodeByIdAsync("3:2");
const ws = {name: page.name, children: page.children.map(c=>({id:c.id,name:c.name,type:c.type}))};
const icon = await figma.getNodeByIdAsync("1:158");
const iconDetail = JSON.stringify(icon, null, 0);
// inspect vector fills inside icon
const grp = icon.children[0];
const vecInfo = grp.children ? grp.children.map(c=>({name:c.name,type:c.type,fills:c.fills,strokes:c.strokes})) : [];
// check button/textfield details
const btn = await figma.getNodeByIdAsync("1:24");
const btnInfo = {fills: btn.fills, cornerRadius: btn.cornerRadius, layoutMode: btn.layoutMode, primaryAxisAlignItems: btn.primaryAxisAlignItems, counterAxisAlignItems: btn.counterAxisAlignItems, padding: [btn.paddingLeft,btn.paddingTop], itemSpacing: btn.itemSpacing, effects: btn.effects, strokes: btn.strokes};
const tf = await figma.getNodeByIdAsync("1:27");
const tfInfo = {fills: tf.fills, cornerRadius: tf.cornerRadius, layoutMode: tf.layoutMode, padding:[tf.paddingLeft,tf.paddingTop,tf.paddingRight,tf.paddingBottom], strokes: tf.strokes, counterAxisAlignItems: tf.counterAxisAlignItems};
// status bar children detail
const sb = await figma.getNodeByIdAsync("1:32");
const sbInfo = sb.children.map(c=>({name:c.name,type:c.type,x:c.x,y:c.y,fills:c.fills}));
const hi = await figma.getNodeByIdAsync("1:42");
const hiInfo = hi.children.map(c=>({name:c.name,type:c.type,x:c.x,y:c.y,fills:c.fills,cornerRadius:c.cornerRadius}));
return JSON.stringify({ws, vecInfo, btnInfo, tfInfo, sbInfo, hiInfo}, null, 1);

