const page = await figma.getNodeByIdAsync("3:2");
await figma.setCurrentPageAsync(page);
await figma.loadFontAsync({family:"Inter",style:"Regular"});
await figma.loadFontAsync({family:"Inter",style:"Medium"});
await figma.loadFontAsync({family:"Inter",style:"Semi Bold"});

const C = {
  black:{r:0,g:0,b:0}, ink:{r:0.067,g:0.067,b:0.067}, gray:{r:0.46,g:0.46,b:0.46},
  gray2:{r:0.71,g:0.71,b:0.71}, surface:{r:0.96,g:0.96,b:0.96}, border:{r:0.9,g:0.9,b:0.9},
  white:{r:1,g:1,b:1}, error:{r:0.83,g:0.15,b:0.15}, dark:{r:0.067,g:0.067,b:0.067}, darkSurface:{r:0.13,g:0.13,b:0.13}
};
const solid = c => [{type:"SOLID",color:c}];
function txt(chars, size, style, color, name){
  const t = figma.createText(); t.fontName={family:"Inter",style}; t.fontSize=size; t.characters=chars; t.fills=solid(color); if(name)t.name=name; return t;
}
function iconInst(id){ const c = figma.getNodeByIdAsync; return null; }
async function inst(id){ const m = await figma.getNodeByIdAsync(id); return m.createInstance(); }
function auto(dir, gap, pad){ const f=figma.createFrame(); f.layoutMode=dir; f.itemSpacing=gap; if(pad!==undefined){f.paddingLeft=pad;f.paddingRight=pad;f.paddingTop=pad;f.paddingBottom=pad;} return f; }

const made = {};

// ---- TabBar ----
{
  const tb = figma.createFrame(); tb.name="TabBar"; tb.resize(375,83); tb.fills=solid(C.white);
  tb.layoutMode="HORIZONTAL"; tb.primaryAxisAlignItems="SPACE_BETWEEN"; tb.counterAxisAlignItems="MIN";
  tb.paddingLeft=12; tb.paddingRight=12; tb.paddingTop=8; tb.itemSpacing=0;
  tb.strokes=[{type:"SOLID",color:C.border}]; tb.strokeWeight=1; tb.strokeAlign="INSIDE";
  const items=[["Icon_Home","1:166","Home"],["Icon_Search","1:171","Shop"],["Icon_Favorites","1:164","Favorites"],["Icon_Bag","1:159","Bag"],["Icon_Profile","1:168","Profile"]];
  for(const [nm,id,label] of items){
    const it = auto("VERTICAL",4); it.name="Tab_"+label; it.counterAxisAlignItems="CENTER"; it.layoutAlign="INHERIT"; it.fills=[];
    const ic = await inst(id); ic.name=nm; it.appendChild(ic);
    const t = txt(label,10,"Medium",C.gray2,"Label"); it.appendChild(t);
    tb.appendChild(it);
  }
  tb.x=0; tb.y=0; page.appendChild(tb); made.TabBar=tb.id;
}

// ---- SheetHeader ----
{
  const sh = figma.createFrame(); sh.name="SheetHeader"; sh.resize(375,48); sh.fills=[];
  const cancel = txt("Cancel",16,"Regular",C.black,"Cancel"); cancel.x=20; cancel.y=15; sh.appendChild(cancel);
  const title = txt("accounts.nike.com",13,"Medium",C.gray,"Title"); title.x=125; title.y=17; sh.appendChild(title);
  const grab = figma.createRectangle(); grab.name="Grabber"; grab.resize(36,4); grab.cornerRadius=2; grab.fills=solid(C.border); grab.x=169.5; grab.y=6; sh.appendChild(grab);
  page.appendChild(sh); made.SheetHeader=sh.id;
}

