{
  const pb = figma.createFrame(); pb.name="ProgressBar"; pb.resize(375,4); pb.fills=solid(C.darkSurface); pb.cornerRadius=2;
  const fill = figma.createRectangle(); fill.name="Fill"; fill.resize(75,4); fill.fills=solid(C.white); fill.cornerRadius=2; fill.x=0; fill.y=0; pb.appendChild(fill);
  pb.clipsContent=true; page.appendChild(pb); made.ProgressBar=pb.id;
}

