async function shell(dark){
  const sb=await inst("1:32"); const hi=await inst("1:42");
  if(dark){
    const recolor=n=>{ if("fills" in n && n.fills!==figma.mixed && Array.isArray(n.fills) && n.fills.length) n.fills=solid(C.white); if("strokes" in n && Array.isArray(n.strokes) && n.strokes.length) n.strokes=solid(C.white); if(n.children) n.children.forEach(recolor); };
    recolor(sb); recolor(hi);
  }
  sb.x=0; sb.y=0; hi.x=0; hi.y=778;
  return [sb,hi];
}
function newFrame(name,x,y,h){const f=figma.createFrame();f.name=name;f.resize(375,h||812);f.x=x;f.y=y;f.fills=solid(C.white);f.clipsContent=true;page.appendChild(f);return f;}
