  const newAv=await inst(avatarId); newAv.name="Avatar"; newAv.resize(56,56);
  av.parent.insertChild(av.parent.children.indexOf(av), newAv); av.remove();
  const lb=r.findOne(c=>c.name==="Label"); lb.characters=label;
  r.resize(w||335,80); r.x=x; r.y=y; f.appendChild(r); return r;
}

