const page = await figma.getNodeByIdAsync("3:2");
await figma.loadFontAsync({family:"Inter",style:"Medium"});
await figma.loadFontAsync({family:"Inter",style:"Semi Bold"});
const BLACK={r:0,g:0,b:0};
const GRAY={r:0.71,g:0.71,b:0.71};
const currentMap={
 "09_Welcome_To_App":"Tab_Home",
 "10_Home":"Tab_Home",
 "11_Discover":"Tab_Home",
 "12_Shop":"Tab_Shop",
 "13_Best_Sellers":"Tab_Shop",
 "14_Jordan_Flight_Essentials":"Tab_Home",
 "15_Product_Detail":"Tab_Shop",
 "16_Style_Matching":"Tab_Shop",
 "17_Stores":"Tab_Shop",
 "18_Playlist_Story":"Tab_Home"
};
function setIconColor(ic, color){
  // recolor vector strokes/fills inside icon instance
  function walk(n){
    if(n.type==="VECTOR"||n.type==="ELLIPSE"||n.type==="RECTANGLE"||n.type==="LINE"){
      try{ if(n.strokes && n.strokes.length) n.strokes=[{type:"SOLID",color}]; }catch(e){}
      try{ if(n.fills && n.fills.length && n.fills[0].visible!==false) n.fills=[{type:"SOLID",color}]; }catch(e){}
    }
    if(n.children) n.children.forEach(walk);
  }
  walk(ic);
}
const done=[];
for(const fname of Object.keys(currentMap)){
  const f = page.children.find(c=>c.name===fname);
  if(!f) continue;
  const tb = f.children.find(c=>c.name==="TabBar");
  if(!tb) continue;
  const curName = currentMap[fname];
  for(const tab of tb.children){
    const lbl = tab.children.find(x=>x.type==="TEXT");
    const ic = tab.children.find(x=>x.type==="INSTANCE");
    const isCur = tab.name===curName;
    if(lbl){
      lbl.fontName = isCur?{family:"Inter",style:"Semi Bold"}:{family:"Inter",style:"Medium"};
      lbl.fills=[{type:"SOLID",color: isCur?BLACK:GRAY}];
    }
    if(ic) setIconColor(ic, isCur?BLACK:GRAY);
  }
  done.push(fname+"->"+curName);
}
return JSON.stringify(done);

