  function firstColor(n){
    let res=null;
    function walk(x){ if(res) return; if((x.type==="TEXT"||x.type==="VECTOR"||x.type==="RECTANGLE"||x.type==="ELLIPSE") && x.fills && x.fills.length && x.fills[0].visible!==false){ res=JSON.stringify(x.fills[0].color); return;} if(x.children) x.children.forEach(walk); }
    walk(n); return res;
  }
  out[f.name]={bg: f.fills[0]&&f.fills[0].color?JSON.stringify(f.fills[0].color):"none", sb: sb?firstColor(sb):"MISSING", hi: hi?firstColor(hi):"MISSING"};
}
