const page = await figma.getNodeByIdAsync("3:2");
const issues=[];
for (const f of page.children) {
  if (f.type!=="FRAME") continue;
  function walk(n, path){
    if (n.type==="TEXT") {
      // detect clipped text: height needed vs actual
      if (n.textAutoResize==="NONE" && n.height < 10) issues.push(f.name+" "+path+" tiny");
    }
    if (n.children) n.children.forEach(c=>walk(c, path+"/"+c.name));
  }
  walk(f, f.name);
  // bottom-most content vs home indicator
  const hi = f.children.find(c=>c.name==="Home Indicator");
  if (hi) {
    for (const c of f.children) {
      if (c.name==="Home Indicator"||c.name==="Status Bar"||c.name==="TabBar") continue;
      if (c.y + c.height > hi.y + 2) issues.push(f.name+" | "+c.name+" overlaps home indicator (bottom "+Math.round(c.y+c.height)+" vs "+Math.round(hi.y)+")");
    }
  }
}
// components inventory
const comps = page.children.filter(c=>c.type==="COMPONENT").map(c=>c.name);
return JSON.stringify({issues, comps},null,1);

