const page = await figma.getNodeByIdAsync("3:2");
const issues=[];
for (const f of page.children) {
  if (f.type!=="FRAME") continue;
  const kids = f.children.filter(c=>c.name!=="Status Bar");
  for (const c of kids) {
    if (c.x < -1 || c.x + c.width > f.width + 1) issues.push(f.name+" | "+c.name+" X-overflow x="+Math.round(c.x)+" w="+Math.round(c.width));
    if (c.y + c.height > f.height + 1) issues.push(f.name+" | "+c.name+" Y-overflow bottom="+Math.round(c.y+c.height)+" fh="+f.height);
  }
  // pairwise overlap among content blocks (exclude full-bleed bg photos & shell)
  const content = kids.filter(c=>!c.name.startsWith("Photo_Welcome")&&!c.name.startsWith("Photo_Home_Story")&&!c.name.startsWith("Photo_Discover")&&c.name!=="Home Indicator"&&c.name!=="TabBar"&&c.name!=="Scrim"&&c.name!=="Overlay");
  for (let i=0;i<content.length;i++) for (let j=i+1;j<content.length;j++) {
    const a=content[i], b=content[j];
    const ox = Math.min(a.x+a.width,b.x+b.width)-Math.max(a.x,b.x);
    const oy = Math.min(a.y+a.height,b.y+b.height)-Math.max(a.y,b.y);
    if (ox>2 && oy>2) issues.push(f.name+" | OVERLAP "+a.name+" & "+b.name+" ("+Math.round(ox)+"x"+Math.round(oy)+")");
  }
}
return JSON.stringify(issues,null,1);

