const page = await figma.getNodeByIdAsync("3:2");
const f03 = page.children.find(c=>c.name==="03_Create_Member");
const GREEN = {r:0.0,g:0.55,b:0.28};
const log=[];
for (const c of f03.children) {
  if (!c.name.startsWith("Checklist_")) continue;
  const ic = c.children.find(x=>x.type==="INSTANCE");
  // instance-level fill
  if (ic.fills && ic.fills.length) { ic.fills=[{type:"SOLID",color:GREEN}]; }
  function recolor(n){
    if (n.type==="VECTOR") {
      if (n.strokes && n.strokes.length) n.strokes=[{type:"SOLID",color:GREEN}];
      if (n.fills && n.fills.length) n.fills=[{type:"SOLID",color:GREEN}];
    }
    if (n.children) n.children.forEach(recolor);
  }
  recolor(ic);
  const v = ic.findOne(x=>x.type==="VECTOR");
  log.push(c.name+" stroke="+JSON.stringify(v.strokes[0].color));
}
return JSON.stringify(log);

const page = await figma.getNodeByIdAsync("3:2");
const out={};
for (const nm of ["01_Welcome","04_Personalize_Intro","09_Welcome_To_App","10_Home"]) {
  const f = page.children.find(c=>c.name===nm);
  const insts=[]; const texts=[];
  function walk(n){ if(n.type==="INSTANCE") insts.push(n.name); if(n.type==="TEXT") texts.push(n.characters); if(n.children) n.children.forEach(walk); }
  walk(f);
  out[nm]={insts, texts};
}
return JSON.stringify(out,null,1);

const page = await figma.getNodeByIdAsync("3:2");
const idToName={};
for (const f of page.children) if (f.type==="FRAME") idToName[f.id]=f.name;
const out=[];
function walk(n, frameName){
  if (n.reactions && n.reactions.length) {
    for (const r of n.reactions) {
      const a = r.actions && r.actions[0];
      const dest = a && a.destinationId;
      out.push(frameName+" | "+n.name+" -> "+(dest? (idToName[dest]||dest) : "BACK"));
    }
  }
  if (n.children) n.children.forEach(c=>walk(c, frameName));
}
for (const f of page.children) if (f.type==="FRAME") walk(f, f.name);
return JSON.stringify({count:out.length, links:out},null,1);

