const page = await figma.getNodeByIdAsync("3:2");
const frames = page.children.filter(c=>c.type==="FRAME");
const comps = page.children.filter(c=>c.type==="COMPONENT");
const refPages = [];
for (const pid of ["0:1","1:2","1:3","1:4"]) {
  const p = await figma.getNodeByIdAsync(pid);
  refPages.push({name:p.name, topChildren:p.children.length, firstChild: p.children[0]?p.children[0].name+" ("+p.children[0].id+")":null});
}
return JSON.stringify({
  workspacePageId: page.id,
  workspacePageName: page.name,
  frameCount: frames.length,
  frameNames: frames.map(f=>f.name),
  componentCount: comps.length,
  componentNames: comps.map(c=>c.name),
  referencePagesIntact: refPages
},null,1);
